#include "simulation.hpp"
#include "vehicle_dynamics.hpp"
#include "vehicle_upgrades.hpp"
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("usage: physics_parity_audit RESOURCE_ROOT [REFERENCE_PROFILES] [CAPTURE_MANIFEST]");Resources r(argv[1]);Geometry road;road.materials.push_back({"road"});Mesh m;m.vertices={{{-100,0,-100}},{{-100,0,500}},{{100,0,500}},{{100,0,-100}}};m.indices={0,1,2,0,2,3};road.meshes.push_back(m);Json out={{"schema","openfo.physics.audit.060"},{"scope","native input values and deterministic Bullet adapter benchmarks; not native trajectory parity"},{"cars",Json::array()}};
for(int id=1;id<=16;id++){auto c=load_vehicle(r,id);Simulation sim(road,c,translate({0,1,0}));for(int i=0;i<300;i++)sim.step({});float settled_y=sim.state().car[13];Input in;in.throttle=1;for(int i=0;i<500;i++)sim.step(in);auto powered=sim.state();in={};in.brake=1;for(int i=0;i<250;i++)sim.step(in);auto stopped=sim.state();if(!std::isfinite(powered.speed)||!std::isfinite(stopped.speed)||powered.speed<=0)throw std::runtime_error("native car did not accelerate finitely");Json row={{"id",id},{"name",c.name},{"stock_mass_kg",c.mass},{"stock_inertia",{c.inertia.x,c.inertia.y,c.inertia.z}},{"tire_peak_longitudinal",c.tire_dynamics.longitudinal},{"tire_peak_lateral",c.tire_dynamics.lateral},{"tarmac_longitudinal_grip",c.tire_dynamics.longitudinal*c.tire_surfaces.at(2).longitudinal},{"tarmac_lateral_grip",c.tire_dynamics.lateral*c.tire_surfaces.at(2).lateral},{"tarmac_rolling_resistance",c.tire_surfaces.at(2).rolling_resistance},{"optimal_slip_ratio",c.tire_dynamics.optimal_slip_ratio},{"optimal_slip_angle_degrees",c.tire_dynamics.optimal_slip_angle},{"settled_body_y",settled_y},{"speed_after_5s_throttle",powered.speed},{"distance_after_5s_throttle",powered.car[14]},{"speed_after_2_5s_brake",stopped.speed},{"curve_points",c.torque_curve.size()},{"redline_rpm",c.max_rpm}};
auto shocks=c;apply_selected_upgrades(shocks,r,{"Upgrades.SHOCKS1"});row["shocks1"]={{"front_spring",shocks.wheels[0].k},{"rear_spring",shocks.wheels[2].k},{"front_rest_length",shocks.wheels[0].rest},{"rear_rest_length",shocks.wheels[2].rest},{"rollbar",shocks.provenance.at("handling").at("rollbar")}};
if(argc>2){auto path=fs::path(argv[2])/("car"+std::to_string(id)+".json");if(fs::exists(path)){auto observed=load_vehicle(r,id,argv[2]);std::ifstream f(path);Json ref;f>>ref;Json comparisons=Json::array();auto wheels=ref.value("wheels_at_capture",Json::array());for(size_t i=0;i<wheels.size()&&i<4;i++){const auto&w=c.wheels[i];const auto&o=wheels[i];comparisons.push_back({{"index",i},{"spring_error",w.k-o.value("spring_constant_native",w.k)},{"bump_error",w.bump-o.value("bump_damping_native",w.bump)},{"rebound_error",w.rebound-o.value("rebound_damping_native",w.rebound)}});}row["reference"]={{"mass_kg",observed.mass},{"stock_mass_delta",c.mass-observed.mass},{"stock_match_not_assumed",true},{"wheel_parameter_errors",comparisons},{"source",observed.profile}};}}
out["cars"].push_back(row);}
if(argc>3){std::ifstream f(argv[3]);Json j;f>>j;size_t dynamic=0,consistent=0,restitution=0,inertia=0,friction=0;for(const auto&o:j.at("objects")){if(o.value("mass_native",0.f)<=0)continue;++dynamic;consistent+=o.value("mass_inverse_consistent",false);restitution+=o.contains("restitution_native");inertia+=o.contains("inertia_diagonal_native");friction+=o.contains("friction_native");}out["capture"]={{"positive_mass_objects",dynamic},{"mass_inverse_consistent",consistent},{"with_restitution",restitution},{"with_inertia",inertia},{"with_friction",friction},{"scope","factory initialized props; no tire trajectory or chassis contact law recovered"}};}
std::cout<<out.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
